INSERT OR IGNORE INTO mission_study_materials (mission_id,title,introduction,explanation,example_code,example_explanation,key_points_json,common_mistakes_json,references_json) VALUES
(20,'Documento HTML','Antes da batalha, entenda Estrutura do documento.','Use Estrutura do documento com semântica e acessibilidade; a estrutura comunica intenção ao navegador e às tecnologias assistivas.','<html lang="pt-BR"><body></body></html>','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Estrutura do documento","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — HTML semântico","url":"https://developer.mozilla.org/en-US/curriculum/core/semantic-html/"}]'),
(21,'Hierarquia de títulos','Antes da batalha, entenda Títulos bem organizados.','Use Títulos bem organizados com semântica e acessibilidade; a estrutura comunica intenção ao navegador e às tecnologias assistivas.','<section><h2>Recursos</h2></section>','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Títulos bem organizados","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — HTML semântico","url":"https://developer.mozilla.org/en-US/curriculum/core/semantic-html/"}]'),
(22,'Semântica de texto','Antes da batalha, entenda Ênfase com significado.','Use Ênfase com significado com semântica e acessibilidade; a estrutura comunica intenção ao navegador e às tecnologias assistivas.','<p><strong>Atenção</strong>: leia os <em>detalhes</em>.</p>','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Ênfase com significado","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — HTML semântico","url":"https://developer.mozilla.org/en-US/curriculum/core/semantic-html/"}]'),
