INSERT OR IGNORE INTO mission_study_materials (mission_id,title,introduction,explanation,example_code,example_explanation,key_points_json,common_mistakes_json,references_json) VALUES
(46,'Tipografia','Antes da batalha, entenda font-family e line-height.','font-family e line-height faz parte de uma interface previsível, responsiva e fácil de manter.','body { font-family: system-ui; line-height: 1.5; }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda font-family e line-height","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(47,'Unidades relativas','Antes da batalha, entenda Tamanhos com rem.','Tamanhos com rem faz parte de uma interface previsível, responsiva e fácil de manter.','h1 { font-size: 2rem; }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Tamanhos com rem","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(48,'Dimensionamento fluido','Antes da batalha, entenda width e max-width.','width e max-width faz parte de uma interface previsível, responsiva e fácil de manter.','.container { width: 90%; max-width: 1200px; }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda width e max-width","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(49,'Box model previsível','Antes da batalha, entenda box-sizing border-box.','box-sizing border-box faz parte de uma interface previsível, responsiva e fácil de manter.','* { box-sizing: border-box; }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda box-sizing border-box","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(50,'Controle de overflow','Antes da batalha, entenda overflow auto.','overflow auto faz parte de uma interface previsível, responsiva e fácil de manter.','.painel { overflow: auto; max-height: 320px; }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda overflow auto","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(51,'Fundos','Antes da batalha, entenda Gradientes sem imagem externa.','Gradientes sem imagem externa faz parte de uma interface previsível, responsiva e fácil de manter.','.hero { background: linear-gradient(135deg,#0f172a,#312e81); }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Gradientes sem imagem externa","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(52,'Elevação','Antes da batalha, entenda box-shadow.','box-shadow faz parte de uma interface previsível, responsiva e fácil de manter.','.card { box-shadow: 0 8px 24px #0003; }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda box-shadow","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(53,'Estados interativos','Antes da batalha, entenda Pseudo-classe hover.','Pseudo-classe hover faz parte de uma interface previsível, responsiva e fácil de manter.','.button:hover { transform: translateY(-2px); }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Pseudo-classe hover","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(54,'Foco acessível','Antes da batalha, entenda focus-visible.','focus-visible faz parte de uma interface previsível, responsiva e fácil de manter.','.button:focus-visible { outline: 3px solid #22d3ee; }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda focus-visible","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(55,'Alinhamento Flex','Antes da batalha, entenda justify e align.','justify e align faz parte de uma interface previsível, responsiva e fácil de manter.','.toolbar { display: flex; justify-content: space-between; align-items: center; }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda justify e align","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(56,'Itens flexíveis','Antes da batalha, entenda flex grow.','flex grow faz parte de uma interface previsível, responsiva e fácil de manter.','.content { flex: 1 1 320px; }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda flex grow","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(57,'CSS Grid','Antes da batalha, entenda Colunas fr.','Colunas fr faz parte de uma interface previsível, responsiva e fácil de manter.','.grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Colunas fr","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
(58,'Grid responsivo','Antes da batalha, entenda minmax e auto-fit.','minmax e auto-fit faz parte de uma interface previsível, responsiva e fácil de manter.','.grid { display: grid; grid-template-columns: repeat(auto-fit,minmax(220px,1fr)); }','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda minmax e auto-fit","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"MDN — CSS e layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-fundamentals/"},{"label":"MDN — CSS Layout","url":"https://developer.mozilla.org/en-US/curriculum/core/css-layout/"}]'),
