INSERT OR IGNORE INTO mission_study_materials (mission_id,title,introduction,explanation,example_code,example_explanation,key_points_json,common_mistakes_json,references_json) VALUES
(97,'Valores distintos','Antes da batalha, entenda DISTINCT.','Use DISTINCT para remover repetições do resultado.','SELECT DISTINCT CATEGORIA_ID FROM PRODUTOS WHERE CATEGORIA_ID IS NOT NULL ORDER BY CATEGORIA_ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda DISTINCT","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(98,'Condições combinadas','Antes da batalha, entenda AND.','AND exige que todas as condições sejam verdadeiras.','SELECT ID,NOME FROM PRODUTOS WHERE ATIVO=1 AND PRECO>=100 ORDER BY ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda AND","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(99,'Alternativas com OR','Antes da batalha, entenda OR.','OR mantém linhas que atendam a pelo menos uma condição.','SELECT ID,NOME FROM PRODUTOS WHERE PRECO<50 OR PRECO>=150 ORDER BY ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda OR","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(100,'Valores ausentes','Antes da batalha, entenda IS NULL.','NULL representa ausência e é comparado com IS NULL.','SELECT ID,NOME FROM PRODUTOS WHERE CATEGORIA_ID IS NULL','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda IS NULL","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(101,'Limite de resultados','Antes da batalha, entenda LIMIT.','LIMIT controla quantas linhas são devolvidas após a ordenação.','SELECT ID,NOME,PRECO FROM PRODUTOS ORDER BY PRECO DESC LIMIT 3','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda LIMIT","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(102,'Aliases legíveis','Antes da batalha, entenda AS.','Aliases deixam colunas calculadas e relatórios mais claros.','SELECT NOME AS PRODUTO,PRECO AS VALOR FROM PRODUTOS WHERE ATIVO=1 ORDER BY ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda AS","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(103,'Contagem','Antes da batalha, entenda COUNT.','COUNT agrega várias linhas em uma contagem.','SELECT COUNT(*) AS TOTAL FROM PRODUTOS WHERE ATIVO=1','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda COUNT","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(104,'Soma agregada','Antes da batalha, entenda SUM.','SUM calcula o total de uma coluna numérica.','SELECT SUM(TOTAL) AS FATURAMENTO FROM VENDAS','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda SUM","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(105,'Média','Antes da batalha, entenda AVG.','AVG calcula média; ROUND controla as casas decimais.','SELECT ROUND(AVG(PRECO),2) AS MEDIA FROM PRODUTOS WHERE ATIVO=1','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda AVG","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(106,'Agrupamento','Antes da batalha, entenda GROUP BY.','GROUP BY produz uma linha agregada por grupo.','SELECT CATEGORIA_ID,COUNT(*) AS TOTAL FROM PRODUTOS WHERE CATEGORIA_ID IS NOT NULL GROUP BY CATEGORIA_ID ORDER BY CATEGORIA_ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda GROUP BY","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(107,'Filtro de grupos','Antes da batalha, entenda HAVING.','HAVING filtra depois do agrupamento.','SELECT PRODUTO_ID,SUM(QUANTIDADE) AS UNIDADES FROM VENDAS GROUP BY PRODUTO_ID HAVING SUM(QUANTIDADE)>=3 ORDER BY PRODUTO_ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda HAVING","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(108,'INNER JOIN','Antes da batalha, entenda Junção obrigatória.','JOIN relaciona linhas por chaves correspondentes.','SELECT P.NOME,C.NOME AS CATEGORIA FROM PRODUTOS P JOIN CATEGORIAS C ON C.ID=P.CATEGORIA_ID ORDER BY P.ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Junção obrigatória","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(109,'LEFT JOIN','Antes da batalha, entenda Junção opcional.','LEFT JOIN preserva todas as linhas da tabela esquerda.','SELECT P.NOME,C.NOME AS CATEGORIA FROM PRODUTOS P LEFT JOIN CATEGORIAS C ON C.ID=P.CATEGORIA_ID ORDER BY P.ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Junção opcional","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(110,'Classificação com CASE','Antes da batalha, entenda CASE.','CASE cria valores condicionais dentro da consulta.','SELECT NOME,CASE WHEN PRECO>=100 THEN ''PREMIUM'' ELSE ''PADRAO'' END AS FAIXA FROM PRODUTOS ORDER BY ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda CASE","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(111,'Fallback com COALESCE','Antes da batalha, entenda COALESCE.','COALESCE escolhe o primeiro valor não nulo.','SELECT NOME,COALESCE(ESTOQUE,0) AS ESTOQUE FROM PRODUTOS ORDER BY ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda COALESCE","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(112,'Subconsulta escalar','Antes da batalha, entenda Subquery.','Uma subconsulta pode calcular o valor usado pelo filtro externo.','SELECT NOME,PRECO FROM PRODUTOS WHERE PRECO>(SELECT AVG(PRECO) FROM PRODUTOS) ORDER BY PRECO','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Subquery","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(113,'IN com subconsulta','Antes da batalha, entenda IN SELECT.','IN pode comparar com o conjunto produzido por outra consulta.','SELECT NOME FROM PRODUTOS WHERE ID IN (SELECT PRODUTO_ID FROM VENDAS WHERE QUANTIDADE>=2) ORDER BY NOME','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda IN SELECT","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(114,'Existência relacionada','Antes da batalha, entenda EXISTS.','EXISTS verifica se a relação possui ao menos uma linha.','SELECT P.NOME FROM PRODUTOS P WHERE EXISTS (SELECT 1 FROM VENDAS V WHERE V.PRODUTO_ID=P.ID) ORDER BY P.ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda EXISTS","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(115,'CTE com WITH','Antes da batalha, entenda WITH.','CTEs nomeiam etapas intermediárias e tornam consultas complexas legíveis.','WITH ATIVOS AS (SELECT * FROM PRODUTOS WHERE ATIVO=1) SELECT NOME,PRECO FROM ATIVOS ORDER BY PRECO DESC','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda WITH","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(116,'Combinação com UNION','Antes da batalha, entenda UNION.','UNION combina resultados compatíveis e remove duplicatas.','SELECT NOME AS ITEM FROM CATEGORIAS UNION SELECT NOME FROM PRODUTOS ORDER BY ITEM','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda UNION","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(117,'Numeração com janela','Antes da batalha, entenda ROW_NUMBER.','Funções de janela calculam métricas sem agrupar as linhas.','SELECT NOME,ROW_NUMBER() OVER (ORDER BY PRECO DESC) AS POSICAO FROM PRODUTOS ORDER BY POSICAO','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda ROW_NUMBER","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(118,'Janela particionada','Antes da batalha, entenda SUM OVER.','PARTITION BY reinicia o cálculo para cada grupo sem reduzir linhas.','SELECT ID,PRODUTO_ID,TOTAL,SUM(TOTAL) OVER (PARTITION BY PRODUTO_ID) AS TOTAL_PRODUTO FROM VENDAS ORDER BY ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda SUM OVER","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(119,'Relatório com múltiplos joins','Antes da batalha, entenda Relatório.','Relatórios profissionais combinam entidades mantendo nomes de coluna claros.','SELECT V.ID,P.NOME,C.NOME AS CATEGORIA,V.TOTAL FROM VENDAS V JOIN PRODUTOS P ON P.ID=V.PRODUTO_ID LEFT JOIN CATEGORIAS C ON C.ID=P.CATEGORIA_ID ORDER BY V.ID','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda Relatório","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]'),
(120,'Análise profissional','Antes da batalha, entenda CTE e agregação.','Separe agregação e apresentação em etapas para construir relatórios auditáveis.','WITH RESUMO AS (SELECT PRODUTO_ID,SUM(QUANTIDADE) AS UNIDADES,SUM(TOTAL) AS RECEITA FROM VENDAS GROUP BY PRODUTO_ID) SELECT P.NOME,R.UNIDADES,R.RECEITA FROM RESUMO R JOIN PRODUTOS P ON P.ID=R.PRODUTO_ID WHERE R.RECEITA>=200 ORDER BY R.RECEITA DESC','O exemplo demonstra o conceito sem entregar a solução específica da missão.','["Entenda CTE e agregação","Prefira código legível e verificável","Teste casos comuns e limites"]','["Copiar o exemplo sem adaptar","Ignorar a estrutura solicitada"]','[{"label":"SQLite — linguagem SQL","url":"https://sqlite.org/lang.html"}]');
