CREATE TABLE VENDAS (ID INTEGER PRIMARY KEY, PRODUTO_ID INTEGER NOT NULL, QUANTIDADE INTEGER NOT NULL, TOTAL REAL NOT NULL, DATA TEXT NOT NULL);','INSERT INTO CATEGORIAS VALUES (1,''Web''),(2,''Dados''),(3,''Mobile'');
INSERT INTO PRODUTOS VALUES (1,''Curso HTML'',1,80,1,12),(2,''Curso CSS'',1,90,1,8),(3,''Curso SQL'',2,120,1,5),(4,''Curso Legado'',NULL,40,0,NULL),(5,''Curso JS'',1,150,1,3);
